parameters.jsCode:
// ───────────────────────────────────────────────────────────
// Coverage Recheck — recompute keyword coverage, redaction and
// rendered length on the refined resume, then continue to render.
// This is the LAST gate: we always ship a PDF; remaining gaps are
// recorded in the tracker.
// ───────────────────────────────────────────────────────────
const REQUIRED_TARGET = 0.8;

function resumeToText(r) {
  const parts = [r.summary, r.location_line];
  for (const g of r.skills || []) parts.push(g.group, ...(g.items || []));
  for (const e of r.experience || []) {
    parts.push(e.employer, e.employer_title, e.employer_summary);
    for (const en of e.engagements || []) parts.push(en.client, en.role, en.industry, ...(en.bullets || []));
  }
  for (const p of r.projects || []) parts.push(p.name, p.description, ...(p.bullets || []));
  for (const ed of r.education || []) parts.push(ed.school, ed.credential);
  return parts.filter(Boolean).join('\n');
}

function hasKeyword(text, kw) {
  const escaped = String(kw).trim()
    .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    .replace(/\s+/g, '[\\s\\-/]*');
  if (!escaped) return true;
  return new RegExp('(^|[^a-z0-9])' + escaped + '([^a-z0-9]|$)', 'i').test(text);
}

function computeCoverage(resume, job_data) {
  const text = resumeToText(resume);
  const req = (job_data.keywords_required || []).map(String).filter(Boolean);
  const pref = (job_data.keywords_preferred || []).map(String).filter(Boolean);
  const matchedReq = req.filter((k) => hasKeyword(text, k));
  const matchedPref = pref.filter((k) => hasKeyword(text, k));
  return {
    target: REQUIRED_TARGET,
    required_total: req.length,
    required_matched: matchedReq.length,
    required_ratio: req.length ? Number((matchedReq.length / req.length).toFixed(3)) : 1,
    missing_required: req.filter((k) => !hasKeyword(text, k)),
    preferred_total: pref.length,
    preferred_matched: matchedPref.length,
    missing_preferred: pref.filter((k) => !hasKeyword(text, k)),
    matched_keywords: [...matchedReq, ...matchedPref],
    word_count: text.split(/\s+/).filter(Boolean).length,
  };
}

// ── Deterministic redaction scrub ─────────────────────────────
// The redaction rule lives in three prompts and was still violated on
// roughly one run in four, because a prompt is a request and not a
// guarantee. This makes it a guarantee. Terms come from House Rules
// config, so there is one list rather than three.
function scrubResume(resume, config) {
  const terms = (config && config.redacted_terms) || [];
  const replacement = (config && config.redaction_replacement) || '[redacted]';
  if (!terms.length) return { resume, redactions: [] };

  const patterns = terms
    .map((t) => String(t).trim())
    .filter(Boolean)
    .map((t) => ({ term: t, re: new RegExp(t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi') }));

  const redactions = [];
  const walk = (v, path) => {
    if (typeof v === 'string') {
      let out = v;
      for (const p of patterns) {
        if (p.re.test(out)) {
          redactions.push({ term: p.term, path });
          out = out.replace(p.re, replacement);
        }
        p.re.lastIndex = 0;
      }
      return out;
    }
    if (Array.isArray(v)) return v.map((x, i) => walk(x, `${path}[${i}]`));
    if (v && typeof v === 'object') {
      const o = {};
      for (const k of Object.keys(v)) o[k] = walk(v[k], path ? `${path}.${k}` : k);
      return o;
    }
    return v;
  };

  return { resume: walk(resume, ''), redactions };
}

// ── Rendered-length estimator ─────────────────────────────────
// Length used to be budgeted in words, which is why five consecutive
// runs shaved words off every bullet and still rendered three pages:
// the renderer bills in LINES. A 128-character bullet and a 106-character
// bullet both occupy two lines, so removing three words from the first
// one removes nothing at all.
//
// Every constant below is read directly off the Render HTML node's own
// CSS - @page letter with 0.65in margins, body Arial 10.5pt/1.35, and
// the exact margins on h2, .entry-head, .entry-title, .entry-sub,
// .engagement-head, ul, li, .skill and .edu. The single fitted value is
// AVG_CHAR_EM: Arial's average advance width as a fraction of font size
// over prose of this kind. 0.46 reproduces the last accepted two-page
// resume at 2.00 pages; the surrounding values give 1.96 at 0.45 and
// 2.08 at 0.48, so the estimate is stable at roughly one line of
// sensitivity per 0.01.
const AVG_CHAR_EM = 0.46;
const PT = {
  BODY_LINE: 10.5 * 1.35,
  SMALL_LINE: 9.5 * 1.35,
  TITLE_LINE: 11 * 1.35,
  PAGE: (11 - 0.65 * 2) * 72,
  BODY_WIDTH: (8.5 - 0.65 * 2) * 72,
};
const H2_PT = 10.5 * 1.35 + 1.5 + 0.9 + 9 + 4.5;
const CHAR_PT = 10.5 * AVG_CHAR_EM;
const BULLET_CHARS = Math.floor((PT.BODY_WIDTH - 12) / CHAR_PT);
const FULL_CHARS = Math.floor(PT.BODY_WIDTH / CHAR_PT);
const LINE_BUDGET = Math.floor((2 * PT.PAGE) / PT.BODY_LINE);
const WASTE_THRESHOLD = 45;

function wrapLines(text, chars) {
  return Math.max(1, Math.ceil(String(text || '').length / chars));
}

function bulletWaste(text, chars) {
  const len = String(text || '').length;
  const lines = Math.max(1, Math.ceil(len / chars));
  const lastLineChars = len - (lines - 1) * chars;
  return { lines, last_line_chars: lastLineChars, wasted_chars: chars - lastLineChars };
}

function estimateLayout(r) {
  let pt = 0;
  const wasteful = [];

  // Header: h1 19pt + .contact lines.
  pt += 19 * 1.35 + 2.25;
  pt += 2 * (PT.SMALL_LINE + 1.5);

  // Summary.
  pt += H2_PT + 6 + wrapLines(r.summary, FULL_CHARS) * PT.BODY_LINE;

  // Skills.
  pt += H2_PT;
  for (const g of r.skills || []) {
    pt += 2.25 + wrapLines(`${g.group}: ${(g.items || []).join(', ')}`, FULL_CHARS) * PT.BODY_LINE;
  }

  // Experience.
  pt += H2_PT;
  for (const emp of r.experience || []) {
    pt += 6.75 + PT.TITLE_LINE;
    if (emp.employer_summary) pt += 3.75 + PT.SMALL_LINE;
    for (const en of emp.engagements || []) {
      pt += 6 + PT.BODY_LINE + 6;
      for (const b of en.bullets || []) {
        const w = bulletWaste(b, BULLET_CHARS);
        pt += w.lines * PT.BODY_LINE + 1.875;
        if (w.lines > 1 && w.wasted_chars >= WASTE_THRESHOLD) {
          wasteful.push({
            client: en.client,
            bullet: b,
            lines: w.lines,
            characters: String(b || '').length,
            wasted_chars: w.wasted_chars,
            hint: `cut ~${w.last_line_chars} characters to drop a full line`,
          });
        }
      }
    }
  }

  // Projects.
  if ((r.projects || []).length) {
    pt += H2_PT;
    for (const p of r.projects) {
      pt += 6.75 + PT.TITLE_LINE + (p.description ? 3.75 + PT.SMALL_LINE : 0) + 6;
      for (const b of p.bullets || []) pt += wrapLines(b, BULLET_CHARS) * PT.BODY_LINE + 1.875;
    }
  }

  // Education.
  pt += H2_PT;
  for (const _ of r.education || []) pt += 4.5 + PT.BODY_LINE;

  // Floor, not round. A document that ends partway through its 98th line has
  // not spilled onto a third page, and rounding up failed the last resume that
  // was actually accepted (it estimates at 98.6 lines).
  const estimatedLines = Math.floor(pt / PT.BODY_LINE);
  wasteful.sort((a, b) => b.wasted_chars - a.wasted_chars);

  return {
    estimated_lines: estimatedLines,
    line_budget: LINE_BUDGET,
    estimated_pages: Number((pt / PT.PAGE).toFixed(2)),
    over_by_lines: Math.max(0, estimatedLines - LINE_BUDGET),
    chars_per_bullet_line: BULLET_CHARS,
    chars_per_full_line: FULL_CHARS,
    wasteful_bullets: wasteful.slice(0, 6),
  };
}

const raw = $json.output;
if (!raw || !raw.experience) {
  throw new Error('Refine Resume output is missing or malformed');
}
const prev = $('Evaluate Gate').first().json;
const config = prev.config || ($('Merge Thesis').first().json || {}).config;
const { resume, redactions } = scrubResume(raw, config);

return {
  resume,
  job_data: prev.job_data,
  coverage: computeCoverage(resume, prev.job_data),
  layout: estimateLayout(resume),
  redactions,
  thesis: prev.thesis || null,
  houseRules: prev.houseRules || '',
  config,
  qa: prev.qa,
  status: 'refined',
};

// ─────────────────────────────────────────────────────────────
// Render HTML — deterministic template. The LLM never touches
// formatting; this node is the only thing that decides layout.
// Contact info is constant: the model cannot typo it.
//
// This node also OWNS two things the LLM has proven unreliable at:
//   1. Engagement ordering (sorted mechanically by end date).
//   2. Page-break discipline (no orphaned headings or lone bullets).
// ─────────────────────────────────────────────────────────────
const CONTACT = {
  name: '[CANDIDATE_NAME]',
  location: '[CANDIDATE_LOCATION]',
  phone: '[CANDIDATE_PHONE]',
  email: '[CANDIDATE_EMAIL]',
  linkedinUrl: '[LINKEDIN_URL]',
  linkedinLabel: '[LINKEDIN_LABEL]',
  githubUrl: '[GITHUB_URL]',
  githubLabel: '[GITHUB_LABEL]',
};

const item = $input.first().json;
/** @type {any} */
const r = item.resume;
if (!r || !r.experience || !r.experience.length) {
  throw new Error('Resume JSON is missing or has no experience entries');
}

// ── helpers ──────────────────────────────────────────────────
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
// Model is instructed to emit plain text; defensively convert any
// stray markdown emphasis instead of letting asterisks leak into the PDF.
function inline(s) {
  let t = esc(s);
  t = t.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
  t = t.replace(/`([^`\n]+)`/g, '$1');
  return t;
}
// Skills are written by an LLM and arrive with inconsistent casing
// ("PostgreSQL" next to "data validation"). Uppercase the first letter of
// each item so the list reads as a deliberate list. Acronyms are untouched
// because only character zero is changed.
function capFirst(s) {
  const t = String(s == null ? '' : s).trim();
  if (!t) return t;
  return t.charAt(0).toUpperCase() + t.slice(1);
}
function sanitize(s) {
  if (!s) return 'Unknown';
  return String(s).replace(/[^a-zA-Z0-9\s\-_]/g, '').replace(/\s+/g, '').trim().substring(0, 40);
}

// ── deterministic engagement ordering ────────────────────────
const MONTHS = {
  jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
  jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
};
function monthValue(token) {
  const t = String(token || '').trim();
  if (/present|current|ongoing/i.test(t)) return 999999;
  const m = t.match(/([A-Za-z]{3})[a-z]*\.?\s+(\d{4})/);
  if (!m) return -1;
  const mi = MONTHS[m[1].toLowerCase()];
  if (mi === undefined) return -1;
  return Number(m[2]) * 12 + mi;
}
function parseRange(range) {
  const raw = String(range || '');
  const parts = raw.split(/\s*[-–—]\s*|\s+to\s+/i);
  if (parts.length < 2) return { start: monthValue(raw), end: monthValue(raw) };
  return { start: monthValue(parts[0]), end: monthValue(parts[parts.length - 1]) };
}
// Sort by end date descending, then start date descending. Entries with
// unparseable dates keep their original relative position at the end.
function sortEngagements(engagements) {
  const decorated = (engagements || []).map((en, i) => {
    const rg = parseRange(en.dates);
    return { en, i, end: rg.end, start: rg.start, bad: rg.end === -1 || rg.start === -1 };
  });
  decorated.sort((a, b) => {
    if (a.bad !== b.bad) return a.bad ? 1 : -1;
    if (a.bad && b.bad) return a.i - b.i;
    if (b.end !== a.end) return b.end - a.end;
    if (b.start !== a.start) return b.start - a.start;
    return a.i - b.i;
  });
  return decorated.map((d) => d.en);
}

// Normalize a date range for DISPLAY only, so the employer line and the
// engagement lines never show mixed dash styles. A plain hyphen-minus is
// used deliberately: some resume parsers mishandle en and em dashes inside
// date ranges, and the visual difference is negligible.
function formatRange(range) {
  return String(range || '').replace(/\s*[-–—]\s*/g, ' - ').trim();
}

// Industry labels share one line with the client, the role, and the date
// range. A long label wraps and strands a word under the dates, which looks
// broken. Two-part labels like "Financial Services / Consumer Lending
// Marketplace" are the usual cause, so anything over the budget collapses to
// its first segment. The dropped detail is always present in the bullets.
const INDUSTRY_CHAR_BUDGET = 26;
function shortIndustry(industry) {
  const full = String(industry || '').trim().replace(/\s+/g, ' ');
  if (full.length <= INDUSTRY_CHAR_BUDGET) return full;
  const first = full.split('/')[0].trim();
  if (first && first.length <= 34) return first;
  const source = first || full;
  if (source.length <= 34) return source;
  return source.slice(0, 32).replace(/\s+\S*$/, '') || source.slice(0, 32);
}

// Strip a trailing parenthetical from the client name when it merely
// restates the industry, e.g. client "Acme Bank (Retail Banking)"
// alongside industry "Retail Banking" printing the same words twice.
function cleanClient(client, industry) {
  let c = String(client || '').trim();
  const ind = String(industry || '').trim().toLowerCase();
  const m = c.match(/^(.*?)\s*\(([^()]+)\)\s*$/);
  if (m && ind) {
    const insideWords = m[2].toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
    const overlap = insideWords.filter((w) => ind.includes(w)).length;
    if (insideWords.length && overlap / insideWords.length >= 0.6) c = m[1].trim();
  }
  return c;
}

const jd = item.job_data || {};
const companyName = jd.company_name || '';
const roleTitle = jd.job_title || '';
const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
// forceBaseName is set by the edit-and-rerender branch so the regenerated
// PDF/MD overwrite the originals instead of picking up today's date.
const baseName = item.forceBaseName || `[CANDIDATE_FILE_PREFIX]_${sanitize(companyName)}_${sanitize(roleTitle)}_${today}`;
const pdfFileName = baseName + '.pdf';
const mdFileName = baseName + '.md';
const pdfTitle = `${CONTACT.name}${roleTitle ? ' — ' + roleTitle : ''}${companyName ? ' — ' + companyName : ''}`;

// Normalize the resume once so HTML and Markdown emit identical content.
const experience = (r.experience || []).map((emp) => ({
  ...emp,
  engagements: sortEngagements(emp.engagements).map((en) => ({
    ...en,
    client: cleanClient(en.client, en.industry),
    industry: shortIndustry(en.industry),
  })),
}));

// ── HTML body ────────────────────────────────────────────────
const out = [];
out.push(`<h1>${esc(CONTACT.name).toUpperCase()}</h1>`);
out.push(`<p class="contact">${esc(CONTACT.location)} &nbsp;|&nbsp; ${esc(CONTACT.phone)} &nbsp;|&nbsp; ${esc(CONTACT.email)}</p>`);
out.push(`<p class="contact"><a href="${esc(CONTACT.linkedinUrl)}">${esc(CONTACT.linkedinLabel)}</a> &nbsp;|&nbsp; <a href="${esc(CONTACT.githubUrl)}">${esc(CONTACT.githubLabel)}</a></p>`);

out.push('<section class="keep"><h2>Professional Summary</h2>');
out.push(`<p>${inline(r.summary || '')}</p></section>`);

out.push('<section class="keep"><h2>Technical Skills</h2>');
for (const g of r.skills || []) {
  out.push(`<p class="skill"><strong>${inline(g.group)}:</strong> ${inline((g.items || []).map(capFirst).join(', '))}</p>`);
}
out.push('</section>');

out.push('<h2>Professional Experience</h2>');
for (const emp of experience) {
