const projects = [];
if (sections['projects']) {
  let p = null;
  for (const raw of sections['projects']) {
    const l = raw.trim();
    if (!l) continue;
    if (l.startsWith('### ')) { p = { name: l.slice(4).trim(), description: '', bullets: [] }; projects.push(p); }
    else if (l.startsWith('- ')) { if (p) p.bullets.push(l.slice(2).trim()); }
