    `<span class="entry-dates">${inline(formatRange(emp.employer_dates))}</span></div>`);
  if (emp.employer_summary) out.push(`<p class="entry-sub">${inline(emp.employer_summary)}</p>`);
  out.push('</div>');
  // An engagement is NOT kept together as one block. Forcing whole blocks to
  // stay on one page is what pushed a five-bullet engagement onto the next
  // page and left inches of dead space behind it, which in turn pushed
  // Education onto a third page. Instead only the heading plus its first two
  // bullets are held together, which is enough to guarantee a heading is never
  // stranded and a page never opens on a lone orphaned bullet. Bullets beyond
  // the second are free to flow across the page boundary, so pages fill.
  const LEAD_BULLETS = 1;
  for (const en of emp.engagements || []) {
    const bullets = en.bullets || [];
    const lead = bullets.slice(0, LEAD_BULLETS);
    const rest = bullets.slice(LEAD_BULLETS);
    out.push('<div class="engagement">');
    out.push('<div class="eng-lead">');
    if (en.client) {
      const roleBit = en.role ? ' — ' + inline(en.role) : '';
      const indBit = en.industry ? '<span class="industry"> | ' + inline(en.industry) + '</span>' : '';
      out.push('<div class="engagement-head">' +
        `<span class="engagement-title">${inline(en.client)}${roleBit}${indBit}</span>` +
        `<span class="entry-dates">${inline(formatRange(en.dates))}</span></div>`);
    }
    if (lead.length) {
      out.push('<ul class="lead">');
      for (const b of lead) out.push(`<li>${inline(b)}</li>`);
      out.push('</ul>');
    }
    out.push('</div>');
    if (rest.length) {
      out.push('<ul class="rest">');
      for (const b of rest) out.push(`<li>${inline(b)}</li>`);
      out.push('</ul>');
    }
    out.push('</div>');
  }
}

if ((r.projects || []).length) {
  out.push('<h2>Projects</h2>');
  for (const p of r.projects) {
    out.push('<div class="engagement">');
    out.push(`<div class="entry-head"><span class="entry-title">${inline(p.name)}</span></div>`);
    if (p.description) out.push(`<p class="entry-sub">${inline(p.description)}</p>`);
    if ((p.bullets || []).length) {
      out.push('<ul>');
      for (const b of p.bullets) out.push(`<li>${inline(b)}</li>`);
      out.push('</ul>');
    }
    out.push('</div>');
  }
}

out.push('<section class="keep"><h2>Education</h2>');
for (const ed of r.education || []) {
  const bits = [inline(ed.credential || ''), inline(ed.location || ''), inline(ed.year || '')].filter(Boolean).join(' &nbsp;|&nbsp; ');
  out.push(`<p class="edu"><strong>${inline(ed.school)}</strong>${bits ? ' — ' + bits : ''}</p>`);
}
out.push('</section>');

const pdfHtmlPayload = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${esc(pdfTitle)}</title>
<style>
  @page { size: letter; margin: 0.65in; }
  * { box-sizing: border-box; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 10.5pt; line-height: 1.35; color: #111; margin: 0; }
  h1 { font-size: 19pt; letter-spacing: 1.5px; margin: 0 0 3px 0; }
  h2 { font-size: 10.5pt; text-transform: uppercase; letter-spacing: 0.8px; border-bottom: 1.2px solid #222; padding-bottom: 2px; margin: 12px 0 6px 0; }
  .contact { font-size: 9.5pt; color: #333; margin: 0 0 2px 0; }
  .entry-head { display: flex; justify-content: space-between; align-items: baseline; margin-top: 9px; gap: 8px; }
  .entry-title { font-weight: bold; font-size: 11pt; }
  .entry-dates { font-size: 9.5pt; color: #444; white-space: nowrap; }
  .entry-sub { margin: 1px 0 4px 0; color: #444; font-size: 9.5pt; }
  .engagement-head { display: flex; justify-content: space-between; align-items: baseline; margin: 7px 0 1px 0; gap: 8px; }
  .engagement-title { font-weight: bold; }
  .industry { font-weight: normal; color: #555; font-size: 9.5pt; }
  ul { margin: 2px 0 6px 0; padding-left: 16px; }
  li { margin-bottom: 2.5px; }
  /* The lead bullets and the remainder are two <ul> elements so they can break
     apart, but they must read as a single list. Collapse the seam. */
  ul.lead { margin-bottom: 0; }
  ul.rest { margin-top: 0; }
  p { margin: 2px 0 6px 0; }
  .skill { margin: 1.5px 0; }
  .edu { margin: 3px 0; }
  a { color: #111; text-decoration: none; }
  strong { font-weight: bold; }

  /* ── Page-break discipline ──────────────────────────────────
     The goal is the smallest set of unbreakable units that still prevents
     ugly breaks. Keeping whole engagements together was too coarse: it
     reserved multi-inch blocks, so a page ended early and the overflow
     cascaded into an extra page. The unbreakable unit is now the engagement
     heading plus its first two bullets. Everything else flows. */
  h1, h2 { break-after: avoid-page; page-break-after: avoid; }
  h2 { break-inside: avoid; page-break-inside: avoid; }
  .keep { break-inside: avoid; page-break-inside: avoid; }
  .employer { break-inside: avoid; page-break-inside: avoid; break-after: avoid-page; page-break-after: avoid; }
  .eng-lead { break-inside: avoid; page-break-inside: avoid; }
  .engagement-head, .entry-head { break-after: avoid-page; page-break-after: avoid; break-inside: avoid; page-break-inside: avoid; }
  ul.lead { break-before: avoid-page; page-break-before: avoid; }
  li { break-inside: avoid; page-break-inside: avoid; }
  p, li { orphans: 2; widows: 2; }
</style>
</head>
<body>
${out.join('\n')}
</body>
</html>`;

// ── Markdown twin (for quick review / git diffing) ───────────
// FORMAT IS A CONTRACT: 'Read & Parse Edited Markdown' parses this
// back into resume JSON. Do not change the line shapes below.
const md = [];
md.push(`# ${CONTACT.name}`);
md.push(`${CONTACT.location} | ${CONTACT.phone} | ${CONTACT.email}`);
md.push(`LinkedIn: ${CONTACT.linkedinUrl} | GitHub: ${CONTACT.githubUrl}`, '');
md.push('## Professional Summary', '', r.summary || '', '');
md.push('## Technical Skills', '');
for (const g of r.skills || []) md.push(`- **${g.group}:** ${(g.items || []).map(capFirst).join(', ')}`);
md.push('', '## Professional Experience', '');
for (const emp of experience) {
  md.push(`### ${emp.employer}${emp.employer_title ? ' — ' + emp.employer_title : ''} | ${formatRange(emp.employer_dates)}`);
  if (emp.employer_summary) md.push(emp.employer_summary);
  md.push('');
  for (const en of emp.engagements || []) {
    if (en.client) md.push(`**${en.client}${en.role ? ' — ' + en.role : ''}${en.industry ? ' | ' + en.industry : ''}** | ${formatRange(en.dates)}`, '');
    for (const b of en.bullets || []) md.push(`- ${b}`);
    md.push('');
  }
}
if ((r.projects || []).length) {
  md.push('## Projects', '');
  for (const p of r.projects) {
    md.push(`### ${p.name}`);
    if (p.description) md.push(p.description);
    for (const b of p.bullets || []) md.push(`- ${b}`);
    md.push('');
  }
}
md.push('## Education', '');
for (const ed of r.education || []) {
  md.push(`- **${ed.school}** — ${[ed.credential, ed.location, ed.year].filter(Boolean).join(' | ')}`);
}
const resumeMarkdown = md.join('\n');

return {
  ...item,
  resume: { ...r, experience },
  pdfHtmlPayload,
  resumeMarkdown,
  pdfFileName,
  mdFileName,
  pdfTitle,
  companyName,
  roleTitle,
  trackerMissing: ((item.coverage || {}).missing_required || []).join('; '),
  qaNotes: [ ...(((item.qa || {}).fabrication_flags) || []), ...(((item.qa || {}).issues) || []) ].join(' | '),
  stretchClaims: (((r.ats_notes || {}).stretch_claims) || []).join(' | '),
};

// Prepare Markdown (Edited) — pull the normalized markdown twin out of
// Render HTML (Edited) so the on-disk .md always matches the shipped PDF.
const r = $('Render HTML (Edited)').first().json;
return {
  resumeMarkdown: r.resumeMarkdown,
  mdFileName: r.mdFileName,
};

// ─────────────────────────────────────────────────────────────
// House Rules — the single source of truth for every rule that
// three different LLM nodes must agree on, plus the candidate-
// specific configuration that used to be hard-coded into all
// three prompts.
//
// Before this node existed, the SOURCE OF TRUTH block and the
// CLIENT IDENTITY AND VENDOR REDACTION block were pasted into
// Resume Generator, QA Review, and Refine Resume. They had already
// drifted: two of them asserted a client industry of
// "Industry / Sub-domain" while the generator's own
// industry rule forbids slashes and caps the field at 26 chars.
//
// Edit rules HERE. All three prompts interpolate
//   {{ $('House Rules').first().json.houseRules }}
// and the deterministic code nodes read CONFIG off this output, so
// a change lands everywhere at once and cannot diverge again.
// ─────────────────────────────────────────────────────────────

const CONFIG = {
  // Strings that must never reach the visible resume. Enforced
  // deterministically in Coverage Check and Coverage Recheck, and
  // re-checked as a safety net in Evaluate Gate.
  redacted_terms: ['[VENDOR_TO_REDACT]'],
  redaction_replacement: 'a third-party vendor platform',

  // Engagements where the Super Resume is ambiguous about who the client
  // actually was, so the model kept promoting an integration target into
  // the client field. Matched on the engagement date range.
  client_overrides: [
    { dates: '[CLIENT_1_DATES]', client: '[CLIENT_1]', industry: '[CLIENT_1_INDUSTRY]' },
  ],

  // Clients that appear on every resume regardless of relevance scoring,
  // because their name recognition is worth more to a reviewer than a
  // marginally better keyword match. Never allowed to displace an
  // engagement that continuity requires. Set to [] to disable.
  always_include_clients: ['[RECOGNIZABLE_CLIENT]'],

  // The employer umbrella. Continuity is measured against this range.
  employer: {
    name: '[EMPLOYER_1]',
    title: '[EMPLOYER_1_TITLE]',
    dates: '[EMPLOYER_1_DATES]',
  },

  // Largest uncovered interval, in months, that may appear between
  // consecutive engagements before a reviewer reads it as unemployment.
  max_gap_months: 4,

  // Trailing gaps get a wider tolerance than interior ones. An interior hole
  // reads as a job loss being concealed; a few months between the most recent
  // engagement and today reads as actively looking, which is already given.
  max_trailing_gap_months: 8,

  education: [
    { school: '[SCHOOL_1]', credential: '[CREDENTIAL_1]', location: '[SCHOOL_1_LOCATION]', year: '[SCHOOL_1_YEAR]' },
    { school: '[SCHOOL_2]', credential: '[CREDENTIAL_2]', location: '[SCHOOL_2_LOCATION]', year: '[SCHOOL_2_YEAR]' },
  ],
};

const overrideLines = CONFIG.client_overrides
  .map((o) => `    - For the ${o.dates} engagement the client is "${o.client}" with industry "${o.industry}".`)
  .join('\n');

const educationLines = CONFIG.education
  .map((e, i) => `  ${i + 1}. school "${e.school}"; credential "${e.credential}"; location "${e.location}"; year "${e.year}"`)
  .join('\n');

const houseRules = `SOURCE OF TRUTH

1. The Super Resume is the sole source of candidate facts.
2. Every claim, technology, methodology, metric, date, responsibility, and qualification in the visible resume must be supported by the Super Resume.
3. The Super Resume's "Baseline Qualifications and Transferable Competencies" section is valid evidence. Do not require a baseline competency to be repeated inside a client engagement before it may be used.
4. Never invent, upgrade, or rename a qualification. Never claim a specific degree field, certification, clearance, authorization, location, technology, or number of years that the Super Resume does not establish.
5. Do not use evasive phrases such as "X-adjacent," "X-style," "similar to X," or "exposure to X."
6. Never upgrade instrumentation work into analysis work. Implementing, configuring, or integrating a tool is not the same as performing the analysis that tool enables. Describe only the work performed.
7. No trajectory, ramp-time, or learning-speed language anywhere. Do not describe moving, ramping, pivoting, transitioning, expanding, or shifting between specializations, do not state how recently or how quickly a capability was acquired, do not apply a self-narrowing label to the candidate, and do not claim learning agility. A resume states completed work.
8. Every metric is a single unambiguous figure. Never combine a range with a plus sign. When the Super Resume gives a range, state the lower bound with no plus sign.
9. No aspirational, eager, hopeful, or intent language anywhere. When evidence for a topic does not exist, omit the topic rather than expressing interest in it.

CLIENT IDENTITY AND VENDOR REDACTION

- Client names are the organizations that engaged the candidate. Use the client name exactly as the Super Resume states it.
- Third-party vendor platforms the candidate merely integrated with or evaluated are not clients and must never occupy the client field. Never replace a real client name with a description of a vendor.
- Where the Super Resume is ambiguous about who the client was, these overrides are authoritative:
${overrideLines}
- These strings must never appear anywhere in the visible resume: ${CONFIG.redacted_terms.map((t) => `"${t}"`).join(', ')}. When describing work that touches these systems, refer to the affected system generically, for example "${CONFIG.redaction_replacement}", without naming it.
- Other vendor names the Super Resume lists as integration targets may be named.

FIXED CANDIDATE FACTS

- Employer umbrella: employer "${CONFIG.employer.name}", employer_title "${CONFIG.employer.title}", employer_dates "${CONFIG.employer.dates}".
- Education, exactly:
${educationLines}
- location_line is exactly "[CANDIDATE_LOCATION]". The renderer prints a fixed contact block, so availability, commute radius, hybrid or remote preferences, county names, and regional qualifiers here are discarded.`;

return {
  ...$json,
  config: CONFIG,
  houseRules,
};

parameters.text:
=Build the job thesis for this posting.

TARGET:
Role: {{ $json.job_data.job_title }}
Company: {{ $json.job_data.company_name }}
Location: {{ $json.job_data.location || 'not specified' }}
Work arrangement: {{ $json.job_data.in_office }}

FULL JOB DESCRIPTION — READ THIS FIRST AND WEIGHT IT HEAVIEST:
{{ $json.job_data.job_description }}

NORMALIZED REQUIRED REQUIREMENTS — the floor, not the argument:
{{ JSON.stringify($json.job_data.requirements_required || [], null, 2) }}

NORMALIZED PREFERRED REQUIREMENTS:
{{ JSON.stringify($json.job_data.requirements_preferred || [], null, 2) }}

HOUSE RULES:
{{ $json.houseRules }}

SUPER RESUME — SOLE CANDIDATE SOURCE OF TRUTH:
{{ $json.superResumeText }}

parameters.inputSchema:
{
  "type": "object",
  "required": [
    "what_the_team_builds",
    "product_surfaces",
    "surface_map",
    "closest_structural_analogue",
    "lead_with",
    "employer_context",
    "differentiators",
    "likely_objection"
  ],
  "properties": {
    "what_the_team_builds": {
      "type": "string",
      "description": "One concrete sentence describing what the software actually does, taken from the job description prose rather than the requirements list."
    },
    "product_surfaces": {
      "type": "array",
      "maxItems": 5,
      "items": {
        "type": "string"
      },
      "description": "Three to five concrete screens, systems, workflows, or user problems this team owns."
    },
    "surface_map": {
      "type": "array",
      "maxItems": 5,
      "items": {
        "type": "object",
        "required": [
          "surface",
          "best_evidence",
          "why"
        ],
        "properties": {
          "surface": {
            "type": "string"
          },
          "best_evidence": {
            "type": "string",
            "description": "A specific engagement or project named in the Super Resume."
          },
          "why": {
            "type": "string",
            "description": "The structural parallel in one sentence."
          }
        }
      }
    },
    "closest_structural_analogue": {
      "type": "string",
      "description": "The single engagement whose system most resembles what this team operates."
    },
    "lead_with": {
      "type": "string",
      "description": "The one accomplishment that should be the first thing this reader encounters, described in one sentence. Not finished bullet text."
    },
    "employer_context": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Technologies, platforms, or domains that are the hiring company's own product or core infrastructure AND are documented in the Super Resume as production experience. Empty array when there is nothing honest to list."
    },
    "differentiators": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Supported work materially relevant to what this team builds but absent from the requirements list."
    },
    "likely_objection": {
      "type": "object",
      "required": [
        "objection",
        "answering_evidence"
      ],
      "properties": {
        "objection": {
          "type": "string"
        },
        "answering_evidence": {
          "type": "string",
          "description": "Evidence already in the Super Resume that makes the objection a non-issue. Never to be argued with in prose."
        }
      }
    }
  }
}

parameters.jsCode:
// Attach the Job Thesis to the pipeline payload.
// The agent node replaces the item with just its own output, so the upstream
// context (job_data, superResumeText, config, houseRules) has to be re-joined.
const base = $('House Rules').first().json;
const thesis = $json.output ?? $json.thesis ?? null;

return [{ json: { ...base, thesis } }];
